tool.command:
mkdir -p run && cd run &&
cp '$d_file'   model.d &&
cp '$dat_file' model.dat &&
rfembc_thermal model $val_upstream $val_downstream 2>&1;
RC=\$?;
if [ -f model.fix ]; then cp model.fix '$output_fix'; else echo "rfembc_thermal: no .fix (exit \${RC})" > '$output_fix'; fi;
if [ -f model.dat ]; then cp model.dat '$output_dat'; else echo "rfembc_thermal: no .dat" > '$output_dat'; fi;
if [ -f model.res ]; then cp model.res '$output_res'; else echo "rfembc_thermal: no .res" > '$output_res'; fi;
exit \${RC}
